SELECT a.*, gz.id AS current_zone_id, gz.zone_name AS current_zone_name, CASE WHEN gz.id IS NULL THEN 1 WHEN gz.id <> a.snapshot_zone_id THEN 1 ELSE 0 END AS zone_changed FROM inspection_anomaly a LEFT JOIN light_group lg ON a.light_group_id = lg.id LEFT JOIN garage_zone gz ON lg.zone_id = gz.id WHERE 1=1
AND a.batch_no LIKE CONCAT('%', #{query.batchNo}, '%')
AND a.group_code LIKE CONCAT('%', #{query.groupCode}, '%')
AND a.anomaly_type = #{query.anomalyType}
AND a.status = #{query.status}
AND gz.id = #{query.zoneId}
AND (gz.id IS NULL OR gz.id <> a.snapshot_zone_id)
ORDER BY a.reported_at DESC, a.id DESC

mapper.update:
UPDATE inspection_anomaly
SET status = 'RETURNED',
    version = version + 1,
    updated_at = #{time}
WHERE id = #{id}
  AND version = #{version}
  AND status = 'PENDING_REVIEW'

UPDATE inspection_anomaly
SET status = 'PENDING_REVIEW',
    supplement_description = #{supplementDescription},
    version = version + 1,
    updated_at = #{time}
WHERE id = #{id}
  AND version = #{version}
  AND status = 'RETURNED'

UPDATE inspection_anomaly
SET status = 'PROCESSING',
    handler = #{operator},
    handling_result = #{handlingResult},
    handled_at = #{time},
    version = version + 1,
    updated_at = #{time}
WHERE id = #{id}
  AND version = #{version}
  AND status = 'CONFIRMED'

UPDATE inspection_anomaly
SET status = 'CLOSED',
    closer = #{operator},
    closed_at = #{time},
    version = version + 1,
    updated_at = #{time}
WHERE id = #{id}
  AND version = #{version}
  AND status = 'PROCESSING'
